select public.request_postgresql_discovery(pg_temp.pg_id(1),pg_temp.id(1),pg_temp.pg_id(6),pg_temp.pg_id(30),pg_temp.pg_id(3),pg_temp.pg_id(20),'enumerate',null,null,null);
