create function pg_temp.scope_request(k int) returns text language sql stable security definer set search_path='' as $$select controller_security.canonical_questionnaire_json(jsonb_build_object('schemaVersion',1,'operationKey',pg_temp.pg_id(k),'scheduleId',pg_temp.pg_id(21),'estateId',pg_temp.pg_id(3),'engagementId',pg_temp.pg_id(20),'connectorId',pg_temp.pg_id(6),'grantId',pg_temp.pg_id(8),'configurationSha256',repeat('a',64),'cadence','* * * * *','preflightRequestId',pg_temp.pg_id(30),'previousScopeId',null,'expiresAt',to_char(transaction_timestamp()+interval '10 minutes','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'reason','Explicit synthetic metadata rediscovery only'))$$;
create function pg_temp.scope_binding(r text,p text) returns text language sql immutable security definer set search_path='' as $$select encode(sha256(convert_to(controller_security.canonical_questionnaire_json(jsonb_build_array('axiom.monitoring-read.'||p,1,pg_temp.pg_id(1)::text,pg_temp.id(1)::text,pg_temp.id(101)::text,encode(sha256(convert_to(r,'UTF8')),'hex'))),'UTF8')),'hex')$$;
create temporary table scheduled_saved(k text primary key,v jsonb,r text);
grant all on scheduled_saved to service_role,human_action_writer,axiom_assessment_controller;
create function pg_temp.changed_scope() returns text language sql stable security definer set search_path='' as $$select controller_security.canonical_questionnaire_json(pg_temp.scope_request(51)::jsonb||jsonb_build_object('preflightRequestId',pg_temp.pg_id(99)))$$;
create function pg_temp.deny(q text) returns void language plpgsql as $$begin
 begin execute q;exception when insufficient_privilege or unique_violation or invalid_parameter_value then
  return;end;
 raise exception 'unexpected scheduled authority';end$$;
set local role human_action_writer;
select pg_temp.deny('select public.record_monitoring_read_scope(pg_temp.pg_id(1),pg_temp.id(1),pg_temp.id(101),pg_temp.scope_request(50),''authorize'',null)');
reset role;
set local role service_role;
select pg_temp.ok(public.preflight_monitoring_read_scope(pg_temp.pg_id(1),pg_temp.id(1),pg_temp.id(101),pg_temp.scope_request(50),'authorize')->>'scopeRevocationAvailable'='true','bounded actual preflight and revocation available');
insert into scheduled_saved values('challenge',public.issue_monitoring_read_mfa_challenge(pg_temp.pg_id(1),pg_temp.id(1),pg_temp.id(101),pg_temp.id(41),pg_temp.pg_id(50),pg_temp.scope_binding(pg_temp.scope_request(50),'authorize'),300000),pg_temp.scope_request(50));
reset role;
update public.mfa_challenges set attempts=1 where id=(select (v->>'id')::uuid from scheduled_saved where k='challenge');
