select public.satisfy_monitoring_read_mfa_challenge(pg_temp.pg_id(1),pg_temp.id(1),pg_temp.id(101),pg_temp.id(41),pg_temp.pg_id(50),pg_temp.scope_binding(r,'authorize'),(v->>'id')::uuid,1,'totp') from scheduled_saved where k='challenge';
select public.consume_monitoring_read_mfa_challenge(pg_temp.pg_id(1),pg_temp.id(1),pg_temp.id(101),pg_temp.id(41),pg_temp.pg_id(50),pg_temp.scope_binding(r,'authorize'),(v->>'id')::uuid,1,pg_temp.pg_id(50)) from scheduled_saved where k='challenge';
reset role;
set local role human_action_writer;
insert into scheduled_saved select 'approval',public.record_monitoring_read_scope(pg_temp.pg_id(1),pg_temp.id(1),pg_temp.id(101),r,'authorize',(v->>'id')::uuid),r from scheduled_saved where k='challenge';
select pg_temp.ok((select v->>'recorded'='true' from scheduled_saved where k='approval'),'exact scope recorded');
select pg_temp.ok(public.record_monitoring_read_scope(pg_temp.pg_id(1),pg_temp.id(1),pg_temp.id(101),r,'authorize',null)=v,'lost approval reply returns original receipt') from scheduled_saved where k='approval';
